import{z as s,x as o,o as l,c as d,q as B,j as t,D as e,d as A,s as i,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"检索与长上下文混合服务","description":"","frontmatter":{"title":"检索与长上下文混合服务","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/lc-retrieval-hybrid-serving.md","filePath":"llm/lc-retrieval-hybrid-serving.md","lastUpdated":1791063341000}'),p={name:"llm/lc-retrieval-hybrid-serving.md"};function C(m,E,D,h,F,c){const r=o("Mermaid");return l(),d("div",null,[E[2]||(E[2]=B('<h1 id="检索与长上下文混合服务" tabindex="-1">检索与长上下文混合服务 <a class="header-anchor" href="#检索与长上下文混合服务" aria-label="Permalink to &quot;检索与长上下文混合服务&quot;">​</a></h1><div class="epigraph"><p>召回负责从十万篇里挑十篇，通读负责把十篇读穿；把两者的活派给同一个窗口，服务就得同时养两种负载。</p><footer>—— 据 Lewis et al., RAG, NeurIPS 2020 与 Liu et al., Lost in the Middle, TACL 2024 整理</footer></div><p><a href="/llm/lc-context-cache-tiers">上一课</a>把上下文缓存立成三层，结束的其实不只是缓存：资源怎么记账、前填怎么切块、缓存怎么分层，这个单元把长上下文的资源侧讲完了。「服务语义」单元从本课起，问的是另一件事——这些资源能力如何变成对调用方可约定的行为。第一个语义问题是负载的双峰：通读型把整份材料推进窗口，检索型只要一个短视图。<a href="/llm/long-context-vs-rag">长上下文是否取代 RAG</a> 已给结论——互补；本课把「互补」落成同一个服务里的接缝。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>双峰负载让调度与缓存同时失灵。长度分布 p50 是 2K、尾部是 64K 的服务，按单峰假设调的水位两头不讨好：缓存树被通读条目撑爆，短请求陪长请求排队，第 1 课的「按积定价」在这里是准入的日常而非口号。语义上还有两笔更隐蔽的账。截断：检索管道丢一个块是协议行为——引用与权限随块走，调用方知道发生了什么；长窗口裁一段是破坏行为——用户以为模型读了全文。引用：通读窗口里位置就是字符下标，检索视图里位置是块号，答案里的引用必须指向正确的那个。两笔账不定义，错误会出现在「答案对、引用错」这种最难归因的地方。</p><p><span class="marginnote">直觉类比：把最相关的文档放上下文两端，像把重点写在文章的开头和结尾——模型的「注意力」对中间段落最不专心，「中间丢失」就是这个现象的实测名字，和人类读者的体验一致。排列是免费的画质旋钮，不值得浪费。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把组合落成三层服务配置。判定层：请求先分类——已圈定、需要全局结构的材料（合同比对、代码库走读）走通读；开放知识库走检索（<a href="/llm/rag-chunking">切分与召回</a>）；两者可串联：召回圈门，通读进房。组装层：上下文组装器按 token 预算装填，全文视图与压缩视图（<a href="/llm/retrieval-based-compaction">检索式压缩</a>）按任务选；排列显式受控——把最相关的放两端，是对<a href="/llm/niah">中间丢失</a>的对策；多跳任务走迭代「检索—读—再查询」（<a href="/llm/multi-hop-retrieval">多跳课</a>），而不是一次塞满。资源层：通读请求走长窗口路径，公共语料吃<a href="/llm/lc-context-cache-tiers">分层缓存</a>；检索请求走短 prefill 路径；两类 SLO 分开报——通读看 TTFT，检索看含召回往返的端到端。</p>',8)),(l(),t(n,null,{default:e(()=>[i(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20CLS%7B%22%E4%BB%BB%E5%8A%A1%E5%88%A4%E5%AE%9A%22%7D%0A%20%20CLS%20--%3E%7C%E5%B7%B2%E5%9C%88%E5%AE%9A%E3%80%81%E8%A6%81%E5%85%A8%E5%B1%80%E7%BB%93%E6%9E%84%7C%20FULL%5B%22%E9%80%9A%E8%AF%BB%E8%B7%AF%E5%BE%84%EF%BC%9A%E9%95%BF%E7%AA%97%E5%8F%A3%20prefill%22%5D%0A%20%20CLS%20--%3E%7C%E5%BC%80%E6%94%BE%E7%9F%A5%E8%AF%86%E5%BA%93%7C%20RETR%5B%22%E5%8F%AC%E5%9B%9E%EF%BC%9A%E5%9D%97%E7%BA%A7%E6%A3%80%E7%B4%A2%22%5D%0A%20%20RETR%20--%3E%20ASM%5B%22%E7%BB%84%E8%A3%85%EF%BC%9A%E9%A2%84%E7%AE%97%E3%80%81%E5%8E%8B%E7%BC%A9%E3%80%81%E6%8E%92%E5%88%97%22%5D%0A%20%20ASM%20--%3E%20SHORT%5B%22%E7%9F%AD%20prefill%20%E8%B7%AF%E5%BE%84%22%5D%0A%20%20CLS%20--%3E%7C%E4%B8%B2%E8%81%94%7C%20BOTH%5B%22%E5%85%88%E5%8F%AC%E5%9B%9E%E5%9C%88%E9%97%A8%EF%BC%8C%E5%86%8D%E9%80%9A%E8%AF%BB%E8%BF%9B%E6%88%BF%22%5D%0A%20%20BOTH%20--%3E%20FULL%0A%20%20FULL%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%EF%BC%9A%E5%BC%95%E7%94%A8%E5%B8%A6%E4%BD%8D%E7%BD%AE%E5%85%83%E6%95%B0%E6%8D%AE%22%5D%0A%20%20SHORT%20--%3E%20GEN%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"组装器为什么必须是服务组件而不是客户端拼串：只有服务知道当前的有效窗口、池水位与缓存状态，才能把「放哪些、放多长、什么顺序」的决策与资源对齐；客户端拼串会把超窗截断变成静默丢内容，把排列退化成偶然。检索与通读的接缝处要传三样元数据：召回分数、块版本、位置映射——引用可回指靠的是第三样。这是「答案对、引用错」的根治处：生成端每句引用都能落回块号或下标，审计才有落点。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"双峰的量级：p50 2K 的检索请求占 256 MiB KV，p50 64K 的通读请求占 8 GiB——一条通读等于 32 条检索。水位准入按页数与积计数，两类负载才能在同一池里共存而不互杀。")],-1)),E[6]||(E[6]=a("p",null,"「答案对、引用错」为什么根治在位置映射，单独画出来：引用从生成端一路回指到原始块，靠的是接缝处那一张映射表。",-1)),(l(),t(n,null,{default:e(()=>[i(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20RETR%5B%22%E5%8F%AC%E5%9B%9E%EF%BC%9A%E5%91%BD%E4%B8%AD%E5%9D%97%207%E3%80%8112%E3%80%813%22%5D%20--%3E%20ASM%5B%22%E7%BB%84%E8%A3%85%E5%99%A8%E6%8C%89%E9%A2%84%E7%AE%97%E8%A3%85%E5%A1%AB%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A%20%20ASM%20--%3E%20MAP%5B%22%E4%BD%8D%E7%BD%AE%E6%98%A0%E5%B0%84%EF%BC%9A%E5%9D%97%E5%8F%B7%20%E2%86%94%20%E5%AD%97%E7%AC%A6%E5%8C%BA%E9%97%B4%22%5D%0A%20%20MAP%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%EF%BC%9A%E6%AF%8F%E5%8F%A5%E5%BC%95%E7%94%A8%E6%8C%82%E4%BD%8D%E7%BD%AE%E5%85%83%E6%95%B0%E6%8D%AE%22%5D%0A%20%20GEN%20--%3E%20AUD%5B%22%E5%AE%A1%E8%AE%A1%EF%BC%9A%E5%BC%95%E7%94%A8%E8%90%BD%E5%9B%9E%E5%9D%97%E5%8F%B7%E6%88%96%E4%B8%8B%E6%A0%87%22%5D%0A%20%20ASM%20-.-%3E%7C%22%E6%98%A0%E5%B0%84%E7%BC%BA%E5%A4%B1%22%7C%20SILENT%5B%22%E6%88%AA%E6%96%AD%E9%9D%99%E9%BB%98%E3%80%81%E5%BC%95%E7%94%A8%E6%82%AC%E7%A9%BA%E3%80%81%E6%97%A0%E4%BB%8E%E5%BD%92%E5%9B%A0%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p><span class="marginnote">术语翻译：「双峰负载」指请求长度的分布出现两个峰——一大批 2K 级的短检索请求，和一小撮 64K 级的长通读请求。就像餐厅同时接外卖单和包场宴席：厨房（调度）、备菜（缓存）、计时（SLO）得分成两条流水线，不能按一种客人的节奏安排。</span></p><p><span class="marginnote">常见误区：容易以为窗口大就「全文自动都在」。超窗截断是悄悄发生的，用户以为模型读了全文，实际中段可能已被裁掉。检索丢块是协议行为——引用与权限随块走、可审计；长窗口裁剪若无显式标注，就是静默破坏。</span></p><p>不重判两种范式的优劣，结论已在<a href="/llm/long-context-vs-rag">对照课</a>立过；不写向量库与嵌入的内部，<a href="/llm/rag-chunking">切分课</a>已立。权限过滤属于检索侧的元数据纪律，本课只约定它进缓存键的接口。通读的质量上限——中间丢失与上下文腐烂——是模型行为，服务能控制的是排列与压缩，不能承诺「在窗口里就会被用上」；这句免责要写进服务文档，否则双峰负载的质量投诉会全部算到系统头上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>混合负载是双峰：通读与检索的长度、SLO、缓存形态都不同，按单峰假设调度两头失灵。</li><li>语义两条：截断要有协议，引用要带位置元数据——「答案对、引用错」由此根治。</li><li>组合三层：任务判定选路径，组装器管预算与排列，资源层分开报 SLO。</li><li>组装器在服务侧：只有服务知道有效窗口与水位，客户端拼串会把截断变静默。</li><li>出处：Lewis et al., RAG（NeurIPS 2020）；Liu et al., Lost in the Middle（TACL 2024）；Xu 等 RECOMP 与 Jiang 等 LongLLMLingua 的压缩口径。</li></ul>',6))])}const L=s(p,[["render",C]]);export{u as __pageData,L as default};
